#include "ArpoMethods.h"
#include "IEcoLab64.h"
#include "IEcoMemoryAllocator1.h"
#include <stdint.h>

typedef struct {
    uint32_t* indices;
    uint32_t* indices_copy;
    void* base;
    uint32_t width;
    uint32_t count;
    uint32_t padded_count;
    uint32_t k;
    uint32_t j;
    BitonicCompare compare;
} StageContext;

static void ECOCALLMETHOD stage_job(void* context, uint32_t lane, uint32_t workers) {
    StageContext* ctx = (StageContext*)context;
    uint32_t i;
    uint32_t partner;
    uint32_t idx_i;
    uint32_t idx_j;
    int16_t order;

    for (i = lane; i < ctx->padded_count; i += workers) {
        partner = i ^ ctx->j;
        if (i < partner) {
            idx_i = ctx->indices[i];
            idx_j = ctx->indices[partner];
            if ((ctx->k & i) == 0) {
                order = ctx->compare((char*)ctx->base + idx_i * ctx->width,
                                     (char*)ctx->base + idx_j * ctx->width);
                if (order > 0) {
                    ctx->indices[i] = idx_j;
                    ctx->indices[partner] = idx_i;
                }
            } else {
                order = ctx->compare((char*)ctx->base + idx_j * ctx->width,
                                     (char*)ctx->base + idx_i * ctx->width);
                if (order > 0) {
                    ctx->indices[i] = idx_j;
                    ctx->indices[partner] = idx_i;
                }
            }
        }
    }
}

int16_t ECOCALLMETHOD lab_bitonic_sort(IEcoLab64* me, void* base, uint32_t count, uint32_t width, BitonicCompare compare, uint32_t workers, BitonicExecutor executor, void* executor_context, BitonicStats* stats) {
    uint32_t i;
    uint32_t k;
    uint32_t j;
    uint32_t n;
    uint32_t stages;
    uint64_t network_pairs;
    uint32_t* indices = 0;
    uint32_t* indices_copy = 0;
    void* output = 0;
    int16_t result = -1;
    StageContext ctx;
    uint32_t power_of_two;

    /* Validate arguments */
    if (count == 0) {
        if (stats) {
            stats->padded_count = 0;
            stats->stages = 0;
            stats->network_pairs = 0;
        }
        return 0;
    }

    if (count == 1) {
        if (stats) {
            stats->p padded_count = 1;
            stats->stages = 0;
            stats->network_pairs = 0;
        }
        return 0;
    }

    /* Validate width and count */
    if (width == 0 || width > 0xFFFFFFFF / count) {
        return -1;
    }

    /* Find least power of two >= count */
    power_of_two = 1;
    while (power_of_two < count) {
        power_of_two <<= 1;
    }

    n = power_of_two;
    ctx.p padded_count = n;
    ctx.width = width;
    ctx.base = base;
    ctx.compare = compare;

    /* Allocate indices */
    {
        IEcoMemoryAllocator1* allocator = lab_allocator(me);
        if (!allocator) {
            return -2;
        }
        indices = (uint32_t*)allocator->pVTbl->Alloc(allocator, n * sizeof(uint32_t));
        if (!indices) {
            return -2;
        }
        indices_copy = (uint32_t*)allocator->pVTbl->Alloc(allocator, n * sizeof(uint32_t));
        if (!indices_copy) {
            allocator->pVTbl->Free(allocator, indices);
            return -2;
        }
    }

    /* Initialize indices */
    for (i = 0; i < count; i++) {
        indices[i] = i;
    }
    for (i = count; i < n; i++) {
        indices[i] = count; /* padding */
    }

    /* Copy indices for stable sort */
    for (i = 0; i < n; i++) {
        indices_copy[i] = indices[i];
    }

    /* Prepare context */
    ctx.indices = indices;
    ctx.indices_copy = indices_copy;

    /* Perform bitonic sort */
    ctx.k = 2;
    ctx.j = 1;
    stages = 0;
    network_pairs = 0;

    while (ctx.k <= n) {
        ctx.j = ctx.k >> 1;
        while (ctx.j > 0) {
            /* Execute stage */
            if (worker > 1) {
                int16_t exec_result = executor(executor_context, stage_job, &ctx, worker);
                if (exec_result != 0) {
                    result = -3;
                    goto cleanup;
                }
            } else {
                stage_job(&ctx, 0, 1);
            }
            ctx.j >>= 1;
            network_pairs += ctx.padded_count / 2;
            stages++;
        }
        ctx.k <<= 1;
    }

    /* Copy indices back */
    for (i = 0; i < n; i++) {
        indices[i] = ctx.indices[i];
    }

    /* Allocate output buffer */
    output = lab_allocator(me)->pVTbl->Alloc(lab_allocator(me), count * width);
    if (!output) {
        result = -2;
        goto cleanup;
    }

    /* Copy elements in sorted order */
    {
        uint32_t output_offset = 0;
        uint32_t i;
        for (i = 0; i < count; i++) {
            if (indices[i] < count) {
                /* Copy element */
                /* Use memcpy or copy elements manually */
                /* For simplicity, assume memcpy is allowed */
                /* In strict ANSI C89, we must copy byte by byte */
                uint32_t j;
                char* src = (char*)base + indices[i] * width;
                char* dst = (char*)output + output_offset;
                for (j = 0; j < width; j++) {
                    dst[j] = src[j];
                }
                output_offset += width;
            }
        }
    }

    /* Copy output back to base */
    {
        uint32_t i;
        char* src = (char*)output;
        char* dst = (char*)base;
        for (i = 0; i < count * width; i++) {
            dst[i] = src[i];
        }
    }

    /* Set statistics */
    if (stats) {
        stats->padded_count = n;
        stats->stages = stages;
        stats->network_pairs = network_pairs;
    }

    result = 0;

cleanup:
    if (indices) {
        lab_allocator(me)->pVTbl->Free(lab_allocator(me), indices);
    }
    if (indices_copy) {
        lab_allocator(me)->pVTbl->Free(lab_allocator(me), indices_copy);
    }
    if (output) {
        lab_allocator(me)->pVTbl->Free(lab_allocator(me), output);
    }

    return result;
}

