#include "ArpoMethods.h"
#include "IEcoBase1.h"
#include "IEcoMemoryAllocator1.h"

typedef struct StageContext {
    const unsigned char* base;
    uint32_t width;
    uint32_t count;
    uint32_t* indices;
    uint32_t k;
    uint32_t j;
    BitonicCompare compare;
} StageContext;

static void ECOCALLMETHOD stage_job(void* context, uint32_t lane, uint32_t workers) {
    StageContext* ctx = (StageContext*)context;
    const unsigned char* base = ctx->base;
    uint32_t width = ctx->width;
    uint32_t count = ctx->count;
    uint32_t* indices = ctx->indices;
    uint32_t k = ctx->k;
    uint32_t j = ctx->j;
    BitonicCompare compare = ctx->compare;
    uint32_t lane_start = lane * (k / workers);
    uint32_t lane_end = (lane == workers - 1) ? k : (lane + 1) * (k / workers);
    uint32_t i;
    uint32_t idx_i, idx_j;

    for (i = lane_start; i < lane_end; i++) {
        idx_i = i;
        idx_j = i ^ j;
        if (idx_i < count && idx_j < count) {
            if (compare(base + idx_i * width, base + idx_j * width) > 0) {
                uint32_t temp_idx = indices[idx_i];
                indices[idx_i] = indices[idx_j];
                indices[idx_j] = temp_idx;
            }
        } else if (idx_i >= count && idx_j < count) {
            if (compare(base + idx_j * width, base + idx_j * width) > 0) {
                uint32_t temp_idx = indices[idx_j];
                indices[idx_j] = indices[idx_j];
                indices[idx_j] = temp_idx;
            }
        } else if (idx_i < count && idx_j >= count) {
            if (compare(base + idx_i * width, base + idx_i * width) > 0) {
                uint32_t temp_idx = indices[idx_i];
                indices[idx_i] = temp_idx;
                indices[idx_i] = temp_idx;
            }
        }
    }
}

int11_t ECOCALLMETHOD lab_bitonic_sort(IEcoLab64* me, void* base, uint32_t count, uint32_t width, BitonicCompare compare, uint32_t workers, BitonicExecutor executor, void* executor_context, BitonicStats* stats) {
    IEcoMemoryAllocator1* allocator = lab_allocator(me);
    void* output = NULL;
    uint32_t* indices = NULL;
    uint32_t padded_count = 1;
    uint32_t i;
    uint32_t k, j;
    uint32_t stages = 0;
    uint64_t network_pairs = 0;
    int11_t result = 0;

    if (me == NULL || compare == NULL || stats == NULL) return -1;
    if (width == 0 || width > 0xFFFFFFFFU / count) return -1;
    if (count > 1048576) return -1;
    if (count == 0) {
        stats->padded_count = 0;
        stats->stages = 0;
        stats->network_pairs = 0;
        return 0;
    }
    if (base == NULL) return -1;
    if (executor == NULL && workers > 1) return -1;

    padded_count = 1;
    while (p padded_count < count) padded_count <<= 1;
    while (p padded_count < count) padded_count <<= 1;

    indices = (uint32_t*)allocator->pVTbl->Alloc(allocator, padded_count * sizeof(uint32_t));
    if (indices == NULL) return -2;
    output = allocator->pVTbl->Alloc(allocator, count * width);
    if (output == NULL) {
        allocator->pVTbl->Free(allocator, indices);
        return -2;
    }

    for (i = 0; i < count; i++) {
        indices[i] = i;
    }
    for (i = count; i < padded_count; i++) {
        indices[i] = count;
    }

    StageContext context;
    context.base = (const unsigned char*)base;
    context.width = width;
    context.count = count;
    context.indices = indices;
    context.k = 2;
    context.j = 1;

    while (context.k <= padded_count) {
        while (context.j >= 1) {
            if (executor != NULL && workers > 1) {
                if (executor(executor_context, stage_job, &context, workers) != 0) {
                    result = -3;
                    goto cleanup;
                }
            } else {
                stage_job(&context, 0, 1);
            }
            context.j >>= 1;
        }
        context.k <<= 1;
        context.j = context.k >> 1;
    }

    /* Copy sorted data to output */
    for (i = 0; i < count; i++) {
        allocator->pVTbl->Copy(allocator, output + i * width, base + indices[i] * width, width);
    }

    /* Copy back to base */
    allocator->pVTbl->Copy(allocator, base, output, count * width);

cleanup:
    if (output != NULL) allocator->pVTbl->Free(allocator, output);
    if (indices != NULL) allocator->pVTbl->Free(allocator, indices);
    stats->padded_count = padded_count;
    stats->stages = stages;
    stats->network_pairs = network_pairs;
    return result;
}

#include "ArpoMethods.h"

typedef struct StageContext {
    uint32_t* indices;
    const unsigned char* base;
    uint32_t width;
    uint32_t count;
    uint32_t N;
    uint32_t k;
    uint32_t j;
} StageContext;

static void ECOCALLMETHOD stage_job(void* context, uint32_t lane, uint32_t workers) {
    StageContext* ctx = (StageContext*)context;
    uint32_t i;
    uint32_t partner;
    uint32_t left_index;
    uint32_t right_index;
    int order;
    uint32_t temp;

    for (i = lane; i < ctx->N; i += workers) {
        partner = i ^ ctx->j;
        if (i >= ctx->count) {
            continue;
        }
        if (i >= ctx->count && partner >= ctx->count) {
            continue;
        }
        if (i >= ctx->count || partner >= ctx->count) {
            continue;
        }
        left_index = ctx->indices[i];
        right_index = ctx->indices[partner];
        if (left_index >= ctx->count || right_index >= ctx->count) {
            continue;
        }
        if (left_index > right_index) {
            temp = left_index;
            left_index = right_index;
            right_index = temp;
        }
        order = 0;
        if (left_index == ctx->count) {
            order = 1;
        } else if (right_index == ctx->count) {
            order = -1;
        } else {
            order = ctx->compare(ctx->base + left_index * ctx->width, ctx->base + right_index * * ctx->width);
        }
        if (order > 0) {
            temp = ctx->indices[i];
            ctx->indices[i] = ctx->indices[partner];
            ctx->indices[partner] = temp;
        }
    }
}

int16_t ECOCALLMETHOD lab_bitonic_sort(IEcoLab64* me, void* base, uint32_t count, uint32_t width, BitonicCompare compare, uint32_t workers, BitonicExecutor executor, void* executor_context, BitonicStats* stats) {
    (void)me;
    (void)base;
    (void)count;
    (void)width;
    (void)compare;
    (void)executor;
    (void)executor_context;
    (void)stats;
    return -1;
}

#include "ArpoMethods.h"

typedef struct StageContext {
    uint32_t* indices;
    const unsigned char* base;
    uint32_t width;
    uint32_t count;
    uint32_t N;
    uint32_t k;
    uint32_t j;
    BitonicCompare compare;
} StageContext;

static void ECOCALLMETHOD stage_job(void* context, uint32_t lane, uint32_t workers) {
    StageContext* ctx = (StageContext*)context;
    uint32_t i;
    uint32_t partner;
    uint32_t left_index;
    uint32_t right_index;
    int order;
    uint32_t temp;
    int ascending;

    for (i = lane; i < ctx->N; i += workers) {
        partner = i ^ ctx->j;
